local currentLanguage = "Chinese"
local languageChanged = false
Language:Dropdown({
    Title = "Current Language",
    Values = {"中文", "English"},
    Value = "中文",
    Callback = function(option)
        if option == "中文" then
            currentLanguage = "Chinese"
        else
            currentLanguage = "English"
        end
        languageChanged = true
    end
})
Language:Button({
    Title = "Apply Language",
    Callback = function()
        if languageChanged then
            WindUI:Notify({
                Title = "Language Change",
                Content = "Please restart the script for changes to take effect",
                Duration = 5,
                Icon = "info"
            })
            languageChanged = false
        else
            WindUI:Notify({
                Title = "Language",
                Content = "Language is already set to " .. currentLanguage,
                Duration = 3,
                Icon = "info"
            })
        end
    end
})
local function translateText(text)
    if not text or type(text) ~= "string" then return text end
    
    if currentLanguage == "Chinese" then
        return Translations[text] or text
    else
        for en, cn in pairs(Translations) do
            if text == cn then
                return en
            end
        end
        return text
    end
end
local function translateGUI(gui)
    if (gui:IsA("TextLabel") or gui:IsA("TextButton") or gui:IsA("TextBox")) then
        pcall(function()
            local text = gui.Text
            if text and text ~= "" then
                local translatedText = translateText(text)
                if translatedText ~= text then
                    gui.Text = translatedText
                end
            end
        end)
    end
end
local function scanAndTranslate()
    for _, gui in ipairs(game:GetService("CoreGui"):GetDescendants()) do
        translateGUI(gui)
    end
