                                    repeat
                                        (game:GetService("RunService")).Heartbeat:wait();
                                        AutoHaki();
                                        EquipWeapon(_G.Settings.Main["Selected Weapon"]);
                                        TweenPlayer(v.HumanoidRootPart.CFrame * Pos);
                                        Attack();
                                        _G.SeaSkill = false;
                                    until not _G.Settings.SeaEvent["Auto Farm Piranha"] or (not v.Parent) or
                                        v.Humanoid.Health <= 0;
                                end
