function CheckFruits()
    for i, v in pairs(RarityFruits) do
        if _G.Settings.Fruit["Store Rarity Fruit"] == "普通-神话" then
            if i == "Common" or i == "Uncommon" or i == "Rare" or i == "Legendary" or i == "Mythical" then
                for _, fruit in ipairs(v) do
                    table.insert(ResultStoreFruits, fruit);
                end
            end
        elseif _G.Settings.Fruit["Store Rarity Fruit"] == "常见-神话" then
            if i == "Uncommon" or i == "Rare" or i == "Legendary" or i == "Mythical" then
                for _, fruit in ipairs(v) do
                    table.insert(ResultStoreFruits, fruit);
                end
            end
        elseif _G.Settings.Fruit["Store Rarity Fruit"] == "稀有-神话" then
            if i == "Rare" or i == "Legendary" or i == "Mythical" then
                for _, fruit in ipairs(v) do
                    table.insert(ResultStoreFruits, fruit);
                end
            end
        elseif _G.Settings.Fruit["Store Rarity Fruit"] == "传奇-神话" then
            if i == "Legendary" or i == "Mythical" then
                for _, fruit in ipairs(v) do
                    table.insert(ResultStoreFruits, fruit);
                end
            end
        elseif _G.Settings.Fruit["Store Rarity Fruit"] == "神话" then
            if i == "Mythical" then
                for _, fruit in ipairs(v) do
                    table.insert(ResultStoreFruits, fruit);
                end
            end
        end
    end
end
