-- 防挂机脚本（VirtualUser自动操作版）
-- 核心逻辑：监听Idled事件，自动模拟鼠标右键操作，避免被判定为挂机

-- 获取核心服务
local VirtualUser = game:GetService("VirtualUser")
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")

-- 获取本地玩家
local localPlayer = Players.LocalPlayer
if not localPlayer then
    warn("无法获取本地玩家！脚本将停止运行")
    return
end

-- 配置项（可根据需要调整）
local CLICK_DELAY = 1 -- 模拟按键按下和抬起的间隔（秒）
local SAFETY_OFFSET = Vector2.new(1, 1) -- 轻微偏移坐标，避免绝对0点可能的检测

-- 防挂机核心函数：模拟鼠标右键点击操作
local function simulateActivity()
    -- 防护：确保当前有相机对象
    local currentCamera = workspace.CurrentCamera
    if not currentCamera then
        warn("当前无相机对象，跳过本次模拟操作")
        return
    end

    -- 模拟鼠标右键按下
    VirtualUser:Button2Down(SAFETY_OFFSET, currentCamera.CFrame)
    -- 等待指定间隔
    task.wait(CLICK_DELAY)
    -- 模拟鼠标右键抬起
    VirtualUser:Button2Up(SAFETY_OFFSET, currentCamera.CFrame)
    
    -- 可选：输出日志，确认脚本在运行
    print("[防挂机脚本] 已触发自动操作，避免挂机判定")
end

-- 绑定Idled事件：当玩家闲置约15秒时触发
local idleConnection = localPlayer.Idled:Connect(function()
    -- 用pcall包裹，防止操作失败导致脚本崩溃
    local success, err = pcall(simulateActivity)
    if not success then
        warn("[防挂机脚本] 模拟操作失败：", err)
    end
end)

-- 额外防护：脚本销毁时断开连接，避免内存泄漏
local function cleanup()
    if idleConnection then
        idleConnection:Disconnect()
        print("[防挂机脚本] 已断开Idled事件连接")
    end
end

-- 监听玩家移除/脚本销毁事件
localPlayer.AncestryChanged:Connect(function(_, parent)
    if not parent then
        cleanup()
    end
end)

-- 输出启动日志
print("[防挂机脚本] 已启动，将自动防止挂机判定")

