TabHandles.Pet:Section({ Title = "进化" })
TabHandles.Pet:Dropdown({
    Title = "宠物",
    Values = { "霓虹守护者", "暗星", "肌肉老师", "赛博龙" },
    Value = "霓虹守护者",
    Callback = function(val)
        if val == "霓虹守护者" then _G.evolvePet = "Neon Guardian"
        elseif val == "暗星" then _G.evolvePet = "Darkstar Hunter"
        elseif val == "肌肉老师" then _G.evolvePet = "Muscle Sensei"
        elseif val == "赛博龙" then _G.evolvePet = "Cybernetic Showdown Dragon"
        end
    end
})
TabHandles.Pet:Toggle({
    Title = "自动进化",
    Value = false,
    Callback = function(state)
        _G.autojh = state
        task.spawn(function()
            while _G.autojh do
                pcall(function()
                    game:GetService("ReplicatedStorage").rEvents.petEvolveEvent:FireServer("evolvePet", _G.evolvePet)
                end)
                task.wait()
            end
        end)
    end
})

