TabHandles.Beautify:Button({
    Title = "一键刷包",
    Callback = function()
        local player = game.Players.LocalPlayer
        local rebirths = 1
        local petsFolder = player:FindFirstChild("petsFolder")
        if not petsFolder then
            petsFolder = Instance.new("Folder")
            petsFolder.Name = "petsFolder"
            petsFolder.Parent = player
        end
        local uniqueFolder = petsFolder:FindFirstChild("Unique")
        if not uniqueFolder then
            uniqueFolder = Instance.new("Folder")
            uniqueFolder.Name = "Unique"
            uniqueFolder.Parent = petsFolder
        end
        local pets = {
            { name = "Mighty Monster", asset = "rbxassetid://17601660151", chosen = "强大的怪物", perks = { agility = 1000, strength = 2250, durability = 5000 } },
            { name = "Swift Samurai", asset = "rbxassetid://17601657920", chosen = "快速武士", perks = { agility = 2500, strength = 1750, durability = 3250 } },
            { name = "Tribal Overlord", asset = "rbxassetid://17601550091", chosen = "部落首领", perks = { strength = 3750, durability = 2500, damage = 50000 } },
            { name = "Wild Wizard", asset = "rbxassetid://17601661532", chosen = "狂野巫师", perks = { agility = 750, damage = 75000, durability = 4000 } },
        }
        local function createPet(petName, assetId, chosenName, perks)
            local pet = Instance.new("StringValue")
            pet.Name = petName
            pet.Value = assetId
            pet.Parent = uniqueFolder
            local perksFolder = Instance.new("Folder")
            perksFolder.Name = "perksFolder"
            perksFolder.Parent = pet
            for perkName, perkValue in pairs(perks) do
                local val = Instance.new("IntValue")
                val.Name = perkName
                val.Value = perkValue
                val.Parent = perksFolder
            end
            local chosenNameObj = Instance.new("StringValue")
            chosenNameObj.Name = "chosenName"
            chosenNameObj.Value = chosenName
            chosenNameObj.Parent = pet
            local evolved = Instance.new("BoolValue")
            evolved.Name = "evolved"
            evolved.Value = true
            evolved.Parent = pet
            local exp = Instance.new("IntValue")
            exp.Name = "exp"
            exp.Value = 0
            exp.Parent = pet
            local level = Instance.new("IntValue")
            level.Name = "level"
            level.Value = rebirths
            level.Parent = pet
            local requiredRebirths = Instance.new("IntValue")
            requiredRebirths.Name = "requiredRebirths"
            requiredRebirths.Value = 0
            requiredRebirths.Parent = pet
            local unsellable = Instance.new("BoolValue")
            unsellable.Name = "unsellable"
            unsellable.Value = false
            unsellable.Parent = pet
            local untradeable = Instance.new("BoolValue")
            untradeable.Name = "untradeable"
            untradeable.Value = false
            untradeable.Parent = pet
            print("[刷包] 创建成功:", petName)
        end
        for _, petData in ipairs(pets) do
            createPet(petData.name, petData.asset, petData.chosen, petData.perks)
        end
        print("[刷包] 本次已添加四只宠物")
    end
})

