local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local LocalPlayer = Players.LocalPlayer

local CTS
local capturingCTS = false
local LastCTSArgs
local loop

local function refreshCTS()
    local char = LocalPlayer.Character
    if not char then return end
    CTS = char:WaitForChild("CharacterMobility"):WaitForChild("CTS")
end

LocalPlayer.CharacterAdded:Connect(function()
    task.wait(1)
    refreshCTS()
    LastCTSArgs = nil
    if capturingCTS then
        capturingCTS = true
    end
end)

refreshCTS()

local mt = getrawmetatable(game)
local old = mt.__namecall
setreadonly(mt, false)
mt.__namecall = function(self, ...)
    local method = getnamecallmethod()
    if method == "FireServer" and self == CTS then
        local args = {...}
        if capturingCTS and not LastCTSArgs then
            LastCTSArgs = args
        end
    end
    return old(self, ...)
end
setreadonly(mt, true)

Tab:Toggle({
    Title = "自动无限闪避",
    Value = false,
    Callback = function(state)
        if state then
            capturingCTS = true
            LastCTSArgs = nil
            if loop then
                loop:Disconnect()
                loop = nil
            end
            loop = RunService.Heartbeat:Connect(function(dt)
                if not CTS or not CTS.Parent then
                    refreshCTS()
                end
                if CTS and LastCTSArgs then
                    if tick() % 0.3 < dt then
                        CTS:FireServer(unpack(LastCTSArgs))
                    end
                end
            end)
        else
            capturingCTS = false
            if loop then
                loop:Disconnect()
                loop = nil
            end
        end
    end
})
local Players = game:GetService("Players")
