local TeleportTab = Tabs.Teleport
if TeleportTab then
    TeleportTab:Section({Title = "传送功能"})

    TeleportTab:Button({
        Title = "传送回电梯",
        Icon = "elevator",
        Callback = function()
            if inLobby then return end
            local targetPart = nil
            for _, obj in ipairs(Services.Workspace:GetDescendants()) do
                if obj:IsA("BasePart") and (obj.Name == "电梯到达点" or obj.Name:lower():find("elevator")) then
                    targetPart = obj
                    break
                end
            end
            if targetPart then
                local char = Services.Players.LocalPlayer.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                if hrp then
                    hrp.CFrame = targetPart.CFrame * CFrame_new(0, 2, 0)
                end
            else
                WindUI:Notify({ Title = "传送", Content = "未找到电梯位置", Duration = 2 })
            end
        end
    })

    TeleportTab:Button({
        Title = "传送至最近玩家",
        Icon = "users",
        Callback = function()
            if inLobby then return end
            local char = Services.Players.LocalPlayer.Character
            if not char then return end
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if not hrp then return end
            local nearest = nil
            local minDist = math.huge
            for _, player in ipairs(Services.Players:GetPlayers()) do
                if player ~= Services.Players.LocalPlayer and player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
                    local dist = (player.Character.HumanoidRootPart.Position - hrp.Position).Magnitude
                    if dist < minDist then
                        minDist = dist
                        nearest = player.Character.HumanoidRootPart
                    end
                end
            end
            if nearest then
                hrp.CFrame = nearest.CFrame * CFrame_new(0, 2, 0)
            else
                WindUI:Notify({ Title = "传送", Content = "附近无其他玩家", Duration = 2 })
            end
        end
    })
end

