Tabs.Main:Section({ Title = "人物功能" })
do
    local speedEnabled = false
    local speedValue = 50
    local originalSpeed = nil
    local speedConnection = nil
    local characterAddedConnection = nil
    local function ApplySpeed(character)
        if not character then return end
        pcall(function()
            local humanoid = character:FindFirstChildOfClass("Humanoid")
            if humanoid then
                if not originalSpeed then
                    originalSpeed = humanoid.WalkSpeed
                end
                humanoid.WalkSpeed = speedValue
            end
        end)
    end
    local function StartSpeed()
        if speedConnection then return end
        local plr = Services.Players.LocalPlayer
        if plr.Character then
            ApplySpeed(plr.Character)
        end
        speedConnection = Services.RunService.Heartbeat:Connect(function()
            if not speedEnabled then
                if speedConnection then
                    speedConnection:Disconnect()
                    speedConnection = nil
                end
                return
            end
            local chr = plr.Character
            if chr then
                ApplySpeed(chr)
            end
        end)
        characterAddedConnection = plr.CharacterAdded:Connect(function(character)
            if speedEnabled then
                task.wait(0.1)
                originalSpeed = nil
                ApplySpeed(character)
            end
        end)
    end
    local function StopSpeed()
        if speedConnection then
            speedConnection:Disconnect()
            speedConnection = nil
        end
        if characterAddedConnection then
            characterAddedConnection:Disconnect()
            characterAddedConnection = nil
        end
        local plr = Services.Players.LocalPlayer
        if plr.Character then
            pcall(function()
                local humanoid = plr.Character:FindFirstChildOfClass("Humanoid")
                if humanoid and originalSpeed then
                    humanoid.WalkSpeed = originalSpeed
                    originalSpeed = nil
                end
            end)
        end
    end
    local speedToggle = Tabs.Main:Toggle({
        Title = "速度加快",
        Default = getgenv().Aero.SpeedEnabled,
        Callback = function(state)
            if inLobby then
                WindUI:Notify({ Title = "提示", Content = "大厅中无法使用此功能", Duration = 2 })
                return
            end
            getgenv().Aero.SpeedEnabled = state
            speedEnabled = state
            if state then
                StartSpeed()
            else
                StopSpeed()
            end
        end
    })
    _G.AeroControls["SpeedEnabled"] = speedToggle
end

