local function safeCall(fn, ...)
    local ok, a, b, c = pcall(fn, ...)
    if ok then
        return a, b, c
    end
    warn("[SZA] " .. tostring(a))
    return nil
end

local function getRequest()
    return http_request or request or (syn and syn.request) or (fluxus and fluxus.request)
end

