local function makeFlag(name, defaultValue)
    local flag = {
        Value = defaultValue,
        _windElem = nil
    }

    function flag:Set(v)
        self.Value = v
        if self._windElem then
            safeCall(function()
                self._windElem:Set(v)
            end)
        end
    end

    function flag:SetValue(v)
        self:Set(v)
    end

    featureFlags[name] = flag
    return flag
end

local function makeValue(name, defaultValue)
    local obj = { Value = defaultValue }
    valueStore[name] = obj
    return obj
end

