local Y_OFFSET = 1.5

local containerTypes = {
    "JunkContainer", "OverpoweredContainer", "MilitaryContainer", "ScratchedContainer",
    "SealedContainer", "GroupContainer", "MetalContainer", "SparkleContainer",
