        local char = lp.Character or lp.CharacterAdded:Wait()
        hrp_new = char:WaitForChild("HumanoidRootPart")
        hum_new = char:WaitForChild("Humanoid")
        clearFlyRes_new()
        char.AncestryChanged:Connect(function(_, parent)
            if not parent then
                clearFlyRes_new()
                bindCharacter_new()
            end
        end)
    end
