local fishOriginalLocation = nil

local sellPoints = {
    Vector3.new(1753.58508, 24.244154, -396.541931),
    Vector3.new(1139.21008, 70.4045868, 1475.69507),
    Vector3.new(-846.960144, 27.6607056, -225.477127),
