local function tryClick(clickPart)
    local detector = clickPart:FindFirstChildOfClass("ClickDetector")
    if detector then
        pcall(function()
            fireclickdetector(detector)
        end)
    end
    local remotes = replicatedStorage:FindFirstChild("Remotes") or replicatedStorage:FindFirstChild("Events")
    if remotes then
        local clickEvents = {"ClickFruit", "HarvestFruit", "CollectFruit", "PickFruit"}
        for _, eventName in ipairs(clickEvents) do
            local event = remotes:FindFirstChild(eventName)
            if event then
                pcall(function()
                    event:FireServer(clickPart)
                end)
            end
        end
    end
end

local function getTargetParts()
    local targets = {}
    for _, tycoon in pairs(workspace:GetChildren()) do
        if tycoon.Name == "Tycoon5" and tycoon:FindFirstChild("Empty") then
            local children = tycoon.Empty:GetChildren()
            local third = children[3]
            if third then
                local innerChildren = third:GetChildren()
                local innerThird = innerChildren[3]
                if innerThird then
                    local clickPart = innerThird:FindFirstChild("ClickFruitPart")
                    if clickPart and clickPart:IsA("BasePart") then
                        table.insert(targets, clickPart)
                    end
                end
            end
        end
    end
    if #targets == 0 then
        for _, obj in pairs(workspace:GetDescendants()) do
            if obj.Name == "ClickFruitPart" and obj:IsA("BasePart") then
                table.insert(targets, obj)
            end
        end
    end
    return targets
end

local function getNearestTarget(character)
    local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")
    if not humanoidRootPart then return nil, 0 end
    local parts = getTargetParts()
    if #parts == 0 then return nil, 0 end
    local nearest = parts[1]
    local minDist = (humanoidRootPart.Position - nearest.Position).Magnitude
    for i = 2, #parts do
        local dist = (humanoidRootPart.Position - parts[i].Position).Magnitude
        if dist < minDist then
            minDist = dist
            nearest = parts[i]
        end
    end
    return nearest, minDist
end

MainTab:Toggle({
    Title = "自动摘柠檬",
    Default = false,
    Callback = function(enabled)
        active = enabled
        if enabled then
            task.spawn(function()
                while active and task.wait() do
                    local character = player.Character
                    if character then
                        local target, dist = getNearestTarget(character)
                        if target and target.Parent then
                            local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
                            if humanoidRootPart then
                                local pos = target.Position
                                if dist > 3 then
                                    humanoidRootPart.CFrame = CFrame.new(pos.X, pos.Y + 2, pos.Z)
                                end
                                pcall(function()
                                    local args = { character, Vector3.new(pos.X, pos.Y, pos.Z) }
                                    updateLook:FireServer(unpack(args))
                                    tryClick(target)
                                end)
                            end
                        end
                    end
                end
            end)
        end
    end
})

