MainTab:Button({
    Title = "藤蔓收获",
    Callback = function()
        pcall(function()
            local character = player.Character
            if not character then return end
            local root = character:FindFirstChild("HumanoidRootPart")
            if not root then return end

            local map = workspace:FindFirstChild("Map")
            if not map then return end
            local sewer = map:FindFirstChild("Sewer")
            if not sewer then return end
            local build = sewer:FindFirstChild("Build")
            if not build then return end
            local mazeEnd = build:FindFirstChild("MazeEnd")
            if not mazeEnd then return end
            local platform = mazeEnd:FindFirstChild("Platform")
            if not platform then return end
            local light = platform:FindFirstChild("Light")
            if not light then return end

            local children = light:GetChildren()
            if #children < 6 then return end
            local target = children[6]
            local pos = nil
            if target then
                if target:IsA("BasePart") then
                    pos = target.Position
                elseif target:IsA("Model") then
                    if target.PrimaryPart then
                        pos = target.PrimaryPart.Position
                    else
                        pos = target:GetPivot().Position
                    end
                elseif target:IsA("Attachment") then
                    pos = target.WorldPosition
                else
                    pcall(function()
                        pos = target.Position
                    end)
                end
            end
            if pos then
                root.CFrame = CFrame.new(pos)
            end
        end)
    end
})

