local verdantRemotes = ReplicatedStorage:WaitForChild("VerdantRemotes")
local fillRemote = verdantRemotes:WaitForChild("VDT_Bucket.Used")
local pourRemote = verdantRemotes:WaitForChild("VDT_Bucket.Poured")
local takeRemote = verdantRemotes:WaitForChild("VDT_Tokens.Take")
local checkpointParts = Workspace:FindFirstChild("Scripted") and Workspace.Scripted:FindFirstChild("CheckpointParts")
BucketTab:Toggle({
    Title = "刷钱",     Value = false,
    Callback = function(state)
                _G.AutoFarmActive = state
        if state then
            print("自动化挂机已开启")
                        task.spawn(function()
                if not checkpointParts then
                    warn("未找到文件夹！🤯")
                    return
                end
                                while _G.AutoFarmActive do
                    local index = 1
                                        while _G.AutoFarmActive do
                        local checkpoint = checkpointParts:FindFirstChild(tostring(index))
                                                if not checkpoint then
                            print("一轮循环结束，准备重置回检查点 1...")
                            break
                        end
                                                if not _G.AutoFarmActive then break end
                        local success, err = pcall(function()
                            local proximityPosition = checkpoint.Drain.Scripted.ProximityPosition
                            local targetPrompt = proximityPosition.ProximityPrompt
                                                        local character = player.Character
                            if character and character:FindFirstChild("HumanoidRootPart") then
                                character.HumanoidRootPart.CFrame = proximityPosition.CFrame + Vector3.new(0, 3, 0)
                                task.wait(0.5)
                            end
                                                        if not _G.AutoFarmActive then return end
                                                        for i = 1, 25 do
                                if not _G.AutoFarmActive then break end
                                fillRemote:FireServer()
                                task.wait(0.08)
                            end
                            if not _G.AutoFarmActive then return end
                                                        pourRemote:FireServer(targetPrompt)
                            task.wait(0.5)
                            if not _G.AutoFarmActive then return end
                                                        for i = 1, 10 do
                                if not _G.AutoFarmActive then break end
                                takeRemote:FireServer(targetPrompt)
                                task.wait(0.3)
                            end
                            task.wait(0.3)
                        end)
                        if not success then
                            warn("检查点 " .. index .. " 出错: " .. tostring(err))
