local function buyItem(count, store, item, name)
	if type(item) ~= "string" then
		notify("错误", "请先选择商品!", 4)
		return
	end
	count = count or 1
	local oldpos = lp.Character.HumanoidRootPart.CFrame;
	local sum = 0;
	while sum < count do
		if dyzh.stopBuy == true then
			Teleport(oldpos)
			return
		end

		local ltem
		for i, v in next, workspace.Stores:children() do
			if v.Name == "ShopItems" and v:FindFirstChild"Box" then
				for j, k in next, v:children() do
					if k.BoxItemName.Value == item then
						ltem = k
					end
				end
			end
		end
		repeat
			task.wait()
		until ltem ~= nil
		Teleport(ltem.Main.CFrame + Vector3.new(0, 1, 5))
		task.wait(0.5)
		repeat
			if dyzh.stopBuy == true then
				Teleport(oldpos)
				return
			end
			newDragModel(ltem, workspace.Stores[name].Counter.CFrame + Vector3.new(0, .6, 0))
			Teleport(ltem.Main.CFrame + Vector3.new(0, 1, 5))
			task.wait(0.2)
		until (ltem.Main.Position - workspace.Stores[name].Counter.Position).Magnitude < 5;
		task.wait(0.4)
		Teleport(workspace.Stores[name].Counter.CFrame + Vector3.new(0, 5, 5))
		task.wait()
		repeat
			task.wait()
			if dyzh.stopBuy == true then
				Teleport(oldpos)
				return
			end
			game.ReplicatedStorage.Interaction.ClientIsDragging:FireServer(ltem)
			game.ReplicatedStorage.NPCDialog.PlayerChatted:InvokeServer(store, "ConfirmPurchase")
		until ltem.Owner.Value == lp or ltem.Owner.Value ~= nil
		for i = 1, 30 do
			newDragModel(ltem, oldpos)
			task.wait(0.01)
		end
		task.wait(0.5)
		sum = sum + 1
	end
	Teleport(oldpos)
end

