Sectionchuanson:Button({
	Title = "获得工具",
	Callback = function()
		if not dyzh.itemset then
			notify("提示", "请先设置传送点", 4)
			return
		end
		local tool = Instance.new("Tool", lp.Backpack)
		tool.Name = "点击你想要传送的物品"
		tool.RequiresHandle = false
		tool.Activated:Connect(function()
			dyzh.cskais = true
			local target = Mouse.Target and Mouse.Target.Parent
			if target then
				if target:FindFirstChild("PurchasedBoxItemName") then
					dyzh.dxmz = target.PurchasedBoxItemName.Value
				elseif target:FindFirstChild("ItemName") then
					dyzh.dxmz = target.ItemName.Value
				end
			end
			for _, v in pairs(workspace.PlayerModels:GetChildren()) do
				if not dyzh.cskais then break end
				local check = v:FindFirstChild("ItemName") or v:FindFirstChild("PurchasedBoxItemName")
				local check2 = v:FindFirstChild("Type")
				if check and check.Value == dyzh.dxmz and v:FindFirstChild("Owner") and tostring(v.Owner.Value) == dyzh.cswjia
					or check2 and check2.Value == dyzh.dxmz and v:FindFirstChild("Owner") and tostring(v.Owner.Value) == dyzh.cswjia then
					local main = v:FindFirstChild("Main")
					if main then
						if (lp.Character.HumanoidRootPart.CFrame.p - main.CFrame.p).Magnitude > 5 then
							Teleport(main.CFrame + Vector3.new(4, 0, 4))
						end
						for _ = 1, 20 do
							if not dyzh.cskais then break end
							game:GetService("ReplicatedStorage").Interaction.ClientIsDragging:FireServer(v)
							v.Main.CFrame = dyzh.itemset
							game:GetService("ReplicatedStorage").Interaction.ClientIsDragging:FireServer(v)
							game:GetService("RunService").Stepped:wait()
						end
					end
				end
			end
		end)
		tool.Parent = lp.Backpack
	end
})

Sectionchuanson:Toggle({
	Title = "点击选择传送物品",
	Value = false,
	Callback = function(state)
		if state then
			dyzh.clickSelectConnection = Mouse.Button1Up:Connect(function()
				local clicked = Mouse.Target
				if clicked and clicked.Parent and clicked.Parent:FindFirstChild("Owner") and tostring(clicked.Parent.Owner.Value) == dyzh.cswjia then
					local model = clicked.Parent:FindFirstAncestor("PlayerModels") and clicked.Parent
					if model then
						if not model:FindFirstChild("SelectionBox") then
							local sb = Instance.new("SelectionBox", model)
							sb.Adornee = model
						else
							model.SelectionBox:Destroy()
						end
					end
				end
			end)
		else
			if dyzh.clickSelectConnection then
				dyzh.clickSelectConnection:Disconnect()
				dyzh.clickSelectConnection = nil
			end
		end
	end
})

