Sectionchuanson:Toggle({
	Title = "框选物品",
	Value = false,
	Callback = function(state)
		if state then
			dyzh.kuangxiu = game:GetService("UserInputService").InputBegan:Connect(function(input)
				if input.UserInputType == Enum.UserInputType.MouseButton1 then
					kuangxuanFrame.Visible = true
					kuangxuanFrame.Position = UDim2.new(0, Mouse.X, 0, Mouse.Y)
					while game:GetService("UserInputService"):IsMouseButtonPressed(Enum.UserInputType.MouseButton1) do
						game:GetService("RunService").RenderStepped:wait()
						kuangxuanFrame.Size = UDim2.new(0, Mouse.X, 0, Mouse.Y) - kuangxuanFrame.Position
						for _, v in pairs(workspace.PlayerModels:GetChildren()) do
							if v:FindFirstChild("Owner") and tostring(v.Owner.Value) == dyzh.cswjia then
								if dyzh.xzemuban and v:FindFirstChild("WoodSection") then
									local screenPos, visible = workspace.CurrentCamera:WorldToScreenPoint(v.WoodSection.CFrame.p)
									if visible and isInFrame(screenPos, kuangxuanFrame) then
										if not v:FindFirstChild("SelectionBox") then
											local sb = Instance.new("SelectionBox", v)
											sb.Adornee = v
										end
									end
								elseif v:FindFirstChild("Main") then
									local screenPos, visible = workspace.CurrentCamera:WorldToScreenPoint(v.Main.CFrame.p)
									if visible and isInFrame(screenPos, kuangxuanFrame) then
										if not v:FindFirstChild("SelectionBox") then
											local sb = Instance.new("SelectionBox", v)
											sb.Adornee = v
										end
									end
								end
							end
						end
					end
					kuangxuanFrame.Size = UDim2.new(0, 1, 0, 1)
					kuangxuanFrame.Visible = false
