Sectionchuanson:Button({
	Title = "开始传送选择的物品",
	Callback = function()
		if not dyzh.itemset then
			notify("提示", "请先设置传送点", 4)
			return
		end
		dyzh.cskais = true
		local oldPos = lp.Character.HumanoidRootPart.CFrame
		for _, v in pairs(workspace.PlayerModels:GetChildren()) do
			if not dyzh.cskais then break end
			if v:FindFirstChild("Owner") and tostring(v.Owner.Value) == dyzh.cswjia and v:FindFirstChild("SelectionBox") then
				if v:FindFirstChild("Main") then
					if (lp.Character.HumanoidRootPart.CFrame.p - v.Main.CFrame.p).Magnitude > 5 then
						Teleport(v.Main.CFrame + Vector3.new(4, 0, 4))
					end
					for _ = 1, 30 do
						if not dyzh.cskais then break end
						game:GetService("ReplicatedStorage").Interaction.ClientIsDragging:FireServer(v)
						v:PivotTo(dyzh.itemset)
						game:GetService("ReplicatedStorage").Interaction.ClientIsDragging:FireServer(v)
						game:GetService("RunService").Stepped:wait()
					end
					v.SelectionBox:Destroy()
				elseif v:FindFirstChild("WoodSection") then
					Teleport(v.WoodSection.CFrame + Vector3.new(4, 0, 4))
					for _ = 1, 70 do
						if not dyzh.cskais then break end
						game:GetService("ReplicatedStorage").Interaction.ClientIsDragging:FireServer(v)
						v.WoodSection.CFrame = dyzh.itemset * CFrame.Angles(math.rad(90), 0, 90)
						game:GetService("ReplicatedStorage").Interaction.ClientIsDragging:FireServer(v)
						game:GetService("RunService").Stepped:wait()
					end
					v.SelectionBox:Destroy()
				end
			end
		end
		Teleport(oldPos)
	end
})

