Section5:Button({
	Title = "处理木材",
	Desc = "点击已砍的树自动分解",
	Callback = function()
		if dyzh.processWood then
			dyzh.processWood = false
			if dyzh.processWoodConnection then
				dyzh.processWoodConnection:Disconnect()
				dyzh.processWoodConnection = nil
			end
			return
		end
		dyzh.processWood = true
		notify("处理树", "请点击一颗已砍的树, 自动分解", 4)
		if dyzh.processWoodConnection then
			dyzh.processWoodConnection:Disconnect()
		end
		dyzh.processWoodConnection = Mouse.Button1Up:Connect(function()
			if not dyzh.processWood then
				if dyzh.processWoodConnection then
					dyzh.processWoodConnection:Disconnect()
					dyzh.processWoodConnection = nil
				end
				return
			end
			pcall(function()
				local oldpos = lp.Character.HumanoidRootPart.CFrame
				local wood = Mouse.Target.Parent
				if wood:FindFirstChild("WoodSection") and wood:FindFirstChild("Owner") and
					(wood.Owner.Value == lp or wood.Owner.Value == nil) then
					if not wood:FindFirstChild("RootCut") and wood.Parent.Name == "TreeRegion" then
						notify("错误!", "这棵树还没有砍!", 4)
						return
					end
					dyzh.processWood = false
					local index = 0
					local treeClass = wood.TreeClass.Value
					local success, tool = getBestAxe(treeClass)
					if not success then return end
					for _, v in pairs(wood:GetDescendants()) do
						if v.Name == "WoodSection" then
							index = index + 1
							if v:FindFirstChild("ID") and v.ID.Value == index then
								lp.Character:MoveTo(v.CFrame.p)
								repeat
									cutPart(v.Parent.CutEvent, v.ID.Value, v.Size.Y, tool, treeClass)
									task.wait()
								until not v:FindFirstChild("Tree Weld")
								task.wait()
							else
								index = index + 1
							end
						end
					end
					task.wait()
					Teleport(oldpos)
				end
			end)
		end)
	end
})

Section5:Button({
	Title = "处理木材并加工",
	Desc = "选树和加工机自动分解并加工",
	Callback = function()
		if dyzh.processWoodMill then
			dyzh.processWoodMill = false
			if dyzh.processWoodMillConnection then
				dyzh.processWoodMillConnection:Disconnect()
				dyzh.processWoodMillConnection = nil
			end
			return
		end
		dyzh.processWoodMill = true
		dyzh.selectedTreeModel = nil
		dyzh.selectedSawmillModel = nil
		notify("处理树!", "请点击一颗已砍的树和加工机, 自动分解并加工", 4)
		if dyzh.processWoodMillConnection then
			dyzh.processWoodMillConnection:Disconnect()
		end
		dyzh.processWoodMillConnection = Mouse.Button1Up:Connect(function()
			pcall(function()
				if not dyzh.processWoodMill then
					if dyzh.processWoodMillConnection then
						dyzh.processWoodMillConnection:Disconnect()
						dyzh.processWoodMillConnection = nil
					end
					return
				end
				local model = Mouse.Target.Parent
				if model:FindFirstChild("Owner") then
					if model.Owner.Value == lp or model.Owner.Value == nil then
						if model:FindFirstChild("WoodSection") and not model:FindFirstChild("RootCut") and model.Parent.Name == "TreeRegion" then
							notify("错误!", "这棵树还没有砍!", 4)
							return
						end
						if model:FindFirstChild("WoodSection") then
							dyzh.selectedTreeModel = model
							notify("处理树", "已选择树", 4)
						end
					end
					if model:FindFirstChild("ItemName") then
						if model.Name:sub(1, 7) == "Sawmill" or model.ItemName.Value:sub(1, 7) == "Sawmill" then
							dyzh.selectedSawmillModel = model
							notify("处理树", "已选择加工机", 4)
						end
					end
				end
			end)
		end)

		spawn(function()
			repeat task.wait() until dyzh.selectedTreeModel and dyzh.selectedSawmillModel
			if dyzh.processWoodMillConnection then
				dyzh.processWoodMillConnection:Disconnect()
				dyzh.processWoodMillConnection = nil
			end
			dyzh.processWoodMill = false
			local wood = dyzh.selectedTreeModel
			local sawmill = dyzh.selectedSawmillModel
			local sawCF = sawmill.Particles.CFrame
			local oldpos = lp.Character.HumanoidRootPart.CFrame
			local treeClass = wood.TreeClass.Value
			local success, tool = getBestAxe(treeClass)
			if not success then return end
			local index = 0
			for _, v in pairs(wood:GetDescendants()) do
				if v.Name == "WoodSection" then
					index = index + 1
					if v:FindFirstChild("ID") and v.ID.Value == index then
						lp.Character:MoveTo(v.CFrame.p)
						repeat
							cutPart(v.Parent.CutEvent, v.ID.Value, v.Size.Y, tool, treeClass)
							task.wait()
						until not v:FindFirstChild("Tree Weld")
						task.wait(1)
						for i = 1, 20 do
							newDragModel(v.Parent, sawCF)
							task.wait()
						end
					else
						index = index + 1
					end
				end
			end
			task.wait()
			for _, log in pairs(workspace.LogModels:GetChildren()) do
				if log:FindFirstChild("Owner") and log.Owner.Value == lp then
					for i = 1, 20 do
						newDragModel(log, sawCF)
						task.wait()
					end
				end
			end
			notify("处理树","已完成加工",4)
			task.wait()
			Teleport(oldpos)
		end)
	end
})

local function plank1x1ByBark(v1)
	local v2 = {}
	v2[1] = v1
	v2[2] = 1 / (v1.Size.x * v1.Size.z)
	if v2[2] < 0.2 then
		v2[2] = 0.3
	end
	v2[3] = math.floor(v1.Size.y / v2[2])
	if v2[3] < 1 then
		v2[3] = 0
	end
	v2[4] = v1.Size.y
	return v2
end

Section5:Button({
	Title = "木板1x1 切割",
	Desc = "点击一块木板自动切1x1",
	Callback = function()
		if dyzh.plank1x1Cut then
			dyzh.plank1x1Cut = false
			if dyzh.plank1x1Connection then
				dyzh.plank1x1Connection:Disconnect()
				dyzh.plank1x1Connection = nil
			end
			return
		end
		dyzh.plank1x1Cut = true
		dyzh.plank1x1Selected = nil
		notify("木板1x1", "请点击一块木板, 自动切割一单位", 4)
		local oldpos = lp.Character.HumanoidRootPart.CFrame
		if dyzh.plank1x1Connection then
			dyzh.plank1x1Connection:Disconnect()
		end
		dyzh.plank1x1Connection = Mouse.Button1Up:Connect(function()
			pcall(function()
				if not dyzh.plank1x1Cut then
					if dyzh.plank1x1Connection then
						dyzh.plank1x1Connection:Disconnect()
						dyzh.plank1x1Connection = nil
					end
					return
				end
				local model = Mouse.Target.Parent
				if model.Name == "Plank" and model:FindFirstChild("Owner") and
					(model.Owner.Value == lp or model.Owner.Value == nil) and model:FindFirstChild("WoodSection") then
					dyzh.plank1x1Selected = model.WoodSection
					dyzh.plank1x1Cut = false
					notify("木板1x1", "已选择木板", 4)
				end
			end)
		end)

		spawn(function()
			repeat task.wait() until dyzh.plank1x1Selected
			if dyzh.plank1x1Connection then
				dyzh.plank1x1Connection:Disconnect()
				dyzh.plank1x1Connection = nil
			end
			local plank = dyzh.plank1x1Selected
			local v0 = plank1x1ByBark(plank)
			local v1 = {}
			local v2 = v0[3]
			if v2 == 0 then return end
			local treeClass = plank.Parent.TreeClass.Value
			local success, tool = getBestAxe(treeClass)
			if not success then return end
			local v3 = false
			local childAddedConn
			childAddedConn = workspace.PlayerModels.ChildAdded:Connect(function(model)
				if model:WaitForChild("Owner").Value == lp and model:FindFirstChild("WoodSection") and
					math.floor(plank1x1ByBark(model.WoodSection)[4]) == math.floor(v0[4] - v0[2]) then
					v3 = true
					v1 = plank1x1ByBark(model.WoodSection)
				end
			end)
			for i = 1, v0[3] do
				v3 = false
				lp.Character:MoveTo(v0[1].CFrame.p)
				repeat
					task.wait()
					cutPart(v0[1].Parent.CutEvent, nil, v0[2], tool, treeClass)
				until v3 or (i == v0[3] and wait(6)) or v0[1].Size.y <= 2
				v0 = v1
			end
			childAddedConn:Disconnect()
			Teleport(oldpos)
		end)
	end
})

