local WindUI = loadstring(game:HttpGet("https://raw.githubusercontent.com/wanhao555/ui/refs/heads/main/UI.luau"))()

local Players = game:GetService("Players")
local UserInputService = game:GetService("UserInputService")
local LocalPlayer = Players.LocalPlayer
local RunService = game:GetService("RunService")
local Camera = workspace.CurrentCamera

local mainWindow = nil
local isWindowOpen = false

local chestCache = {}
local selectedChestName = "1"
local ChestDropdown = nil

local MonsterESP = true
local MonsterAim = true
local wallCheck = false
local aimSmoothness = 0
local aimFOV = 150

local FOVCircle = Drawing.new("Circle")
FOVCircle.Visible = false
FOVCircle.Thickness = 1.5
FOVCircle.NumSides = 40
FOVCircle.Color = Color3.fromRGB(0, 200, 255)
FOVCircle.Radius = aimFOV
FOVCircle.Transparency = 0.5
FOVCircle.Filled = false

local lastMonsterCacheTime = 0
local lastESPUpdate = 0

local RED_COLOR_NAMES = {"Really red", "Persimmon", "Crimson", "Bright red", "Daisy", "Maroon"}
local YELLOW_COLOR_NAMES = {"New Yeller", "Deep orange", "Bright yellow", "Gold", "Golden", "Pastel yellow"}

local function getSpecialFolder()
    local g = workspace:FindFirstChild("Game")
    if not g then return nil end
    local i = g:FindFirstChild("Items")
    if not i then return nil end
    local b = i:FindFirstChild("Boxes")
    if not b then return nil end
    return b:FindFirstChild("Special")
end

local function scanRarityChests()
    chestCache = {}
    local folder = getSpecialFolder()
    if not folder then return 0 end

    for _, desc in ipairs(folder:GetDescendants()) do
        if desc:IsA("Highlight") and desc.Name == "ChestHighlight" then
            desc:Destroy()
        end
    end

    local count = 0
    for _, child in ipairs(folder:GetChildren()) do
        if count >= 10 then break end
        local cf = nil
        if child:IsA("Model") then cf = child:GetPivot()
        elseif child:IsA("BasePart") then cf = child.CFrame
        else
            local p = child:FindFirstChildWhichIsA("BasePart", true)
            if p then cf = p.CFrame end
        end

        if cf then
            local targetColor = nil
            for _, p in ipairs(child:GetDescendants()) do
                if p:IsA("BasePart") then
                    local cName = p.BrickColor.Name
                    for _, n in ipairs(RED_COLOR_NAMES) do
                        if cName == n then targetColor = "Red" break end
                    end
                    if not targetColor then
                        for _, n in ipairs(YELLOW_COLOR_NAMES) do
                            if cName == n then targetColor = "Yellow" break end
                        end
                    end
                    if targetColor then break end
                end
            end

            if targetColor then
                local hl = child:FindFirstChild("ChestHighlight")
                if not hl then
                    hl = Instance.new("Highlight")
                    hl.Name = "ChestHighlight"
                    hl.FillTransparency = 0.6
                    hl.OutlineTransparency = 0
                    hl.Adornee = child
                    hl.Parent = child
                    if targetColor == "Red" then
                        hl.FillColor = Color3.fromRGB(255, 50, 50)
                        hl.OutlineColor = Color3.fromRGB(255, 50, 50)
                    else
                        hl.FillColor = Color3.fromRGB(255, 215, 0)
                        hl.OutlineColor = Color3.fromRGB(255, 215, 0)
                    end
                end
                count = count + 1
                table.insert(chestCache, { Instance = child })
            end
        end
    end
    return #chestCache
end

local function teleportToSelectedChest(chestName)
    local idx = tonumber(chestName)
    if not idx then return false, "请选择正确的数字编号" end
    local item = chestCache[idx]
    if not item then return false, "该编号箱子不存在或已消失" end
    
    local inst = item.Instance
    if not inst or not inst:IsDescendantOf(workspace) then
        table.remove(chestCache, idx)
        refreshList()
        return false, "该宝箱已消失，已自动移除"
    end

    local targetCF = nil
    if inst:IsA("Model") then targetCF = inst:GetPivot()
    elseif inst:IsA("BasePart") then targetCF = inst.CFrame
    else
        local p = inst:FindFirstChildWhichIsA("BasePart", true)
        if p then targetCF = p.CFrame end
    end
    if not targetCF then return false, "无法获取坐标" end

    local pos = targetCF.Position
    local char = LocalPlayer.Character
    local myPos = char and char:FindFirstChild("HumanoidRootPart") and char.HumanoidRootPart.Position
    if pos.Y < -50 or pos.Magnitude < 5 or (myPos and (pos - myPos).Magnitude < 2) then
        table.remove(chestCache, idx)
        refreshList()
        return false, "该宝箱已损坏，已自动移除"
    end

    if char then
        local finalCF = targetCF + Vector3.new(0, 3, 0)
        if char:IsA("Model") then char:PivotTo(finalCF)
        elseif char:FindFirstChild("HumanoidRootPart") then char.HumanoidRootPart.CFrame = finalCF end
        return true, "传送成功"
    end
    return false, "未找到角色实体"
end

local function getMonsterPart(monster)
    local part = monster:FindFirstChild("Head")
    if part then return part end
    part = monster:FindFirstChild("UpperTorso")
    if part then return part end
    return monster:FindFirstChild("HumanoidRootPart")
end

local function hasClearLineOfSight(fromPos, toPos, targetModel)
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = {LocalPlayer.Character}
    local direction = (toPos - fromPos).Unit
    local distance = (toPos - fromPos).Magnitude
    local result = workspace:Raycast(fromPos, direction * distance, params)
    if result then
        local hit = result.Instance
        if hit and hit:IsDescendantOf(targetModel) then return true end
        return false
    end
    return true
end

local function getClosestMonster()
    if tick() - lastMonsterCacheTime < 0.01 then return nil end
    lastMonsterCacheTime = tick()
    local monsters = workspace:FindFirstChild("NPCs") and workspace.NPCs:FindFirstChild("Zombies")
    if not monsters then return nil end
    local bestTarget = nil
    local bestDist = math.huge
    local screenCenter = Vector2.new(Camera.ViewportSize.X / 2, Camera.ViewportSize.Y / 2)
    for _, monster in ipairs(monsters:GetChildren()) do
        local part = getMonsterPart(monster)
        if part then
            if wallCheck then
                if not hasClearLineOfSight(Camera.CFrame.Position, part.Position, monster) then continue end
            end
            local screenPos, onScreen = Camera:WorldToViewportPoint(part.Position)
            if onScreen then
                local screenDist = (Vector2.new(screenPos.X, screenPos.Y) - screenCenter).Magnitude
                if screenDist <= aimFOV then
                    local dist = (Camera.CFrame.Position - part.Position).Magnitude
                    if dist < bestDist then
                        bestDist = dist
                        bestTarget = monster
                    end
                end
            end
        end
    end
    return bestTarget
end

local function updateMonsterESP()
    if tick() - lastESPUpdate < 0.25 then return end
    lastESPUpdate = tick()
    local monsters = workspace:FindFirstChild("NPCs") and workspace.NPCs:FindFirstChild("Zombies")
    if not monsters then return end
    for _, monster in ipairs(monsters:GetChildren()) do
        local hum = monster:FindFirstChildOfClass("Humanoid")
        local alive = hum and hum.Health > 0
        if MonsterESP and monster.Parent and alive then
            local hl = monster:FindFirstChild("MonsterHighlight")
            if not hl then
                hl = Instance.new("Highlight")
                hl.Name = "MonsterHighlight"
                hl.FillColor = Color3.fromRGB(255, 50, 50)
                hl.OutlineColor = Color3.fromRGB(255, 0, 0)
                hl.FillTransparency = 0.5
                hl.OutlineTransparency = 0
                hl.Adornee = monster
                hl.Parent = monster
            end
        else
            local hl = monster:FindFirstChild("MonsterHighlight")
            if hl then hl:Destroy() end
        end
    end
end

local function onRenderStep()
    if MonsterAim and FOVCircle then
        FOVCircle.Visible = true
        FOVCircle.Position = Vector2.new(Camera.ViewportSize.X / 2, Camera.ViewportSize.Y / 2)
        FOVCircle.Radius = aimFOV
    elseif FOVCircle then
        FOVCircle.Visible = false
    end

    if not MonsterAim then return end
    local target = getClosestMonster()
    if target and target.Parent then
        local targetPart = getMonsterPart(target)
        if targetPart then
            if aimSmoothness == 0 then
                Camera.CFrame = CFrame.new(Camera.CFrame.Position, targetPart.Position)
            else
                local targetCF = CFrame.new(Camera.CFrame.Position, targetPart.Position)
                Camera.CFrame = Camera.CFrame:Lerp(targetCF, aimSmoothness)
            end
        end
    end
end

local function refreshList()
    scanRarityChests()
    if ChestDropdown then
        if #chestCache == 0 then
            if selectedChestName ~= "" then selectedChestName = "" end
        else
            local idx = tonumber(selectedChestName)
            if not idx or idx < 1 or idx > #chestCache then
                selectedChestName = "1"
            end
        end
        ChestDropdown:SetValue(selectedChestName)
    end
end

