local connection
local lastAttack = 0
local cooldown = 0.01

local function getNearestZombie()
    local char = localPlayer.Character
    if not char then return nil end
    local root = char:FindFirstChild("HumanoidRootPart")
    if not root then return nil end

    local nearest = nil
    local minDist = math.huge
    local activeFolder = workspace:FindFirstChild("ActiveZombies")
    if not activeFolder then return nil end

    for _, zombie in pairs(activeFolder:GetChildren()) do
        local head = zombie:FindFirstChild("HeadHitbox")
        local hum = zombie:FindFirstChildOfClass("Humanoid")
        if head and hum and hum.Health > 0 then
            local dist = (root.Position - head.Position).Magnitude
            if dist < minDist then
                minDist = dist
                nearest = zombie
            end
        end
    end
    return nearest
end

