local function attackBlock(block)
    if not block or not block:IsA("BasePart") then return end
    local success, err = pcall(function()
        remote:InvokeServer(block)
    end)
    if success then
        attackCount = attackCount + 1
        if attackStatusLabel then
            attackStatusLabel.Text = "攻击次数: " .. attackCount
        end
    else
        warn("攻击失败:", err)
    end
end

local function startAutoAttack()
    if autoAttackConnection then return end
    isAutoAttackEnabled = true
    
    autoAttackConnection = game:GetService("RunService").Heartbeat:Connect(function()
        if not isAutoAttackEnabled then return end
        
        for _, blockName in ipairs(blockNames) do
            local target = workspace.Blocks:FindFirstChild(blockName)
            if target then
                attackBlock(target)
            end
        end
    end)
end

local function stopAutoAttack()
    isAutoAttackEnabled = false
    if autoAttackConnection then
        autoAttackConnection:Disconnect()
        autoAttackConnection = nil
    end
end

local isAutoWinEnabled = false
local autoWinConnection = nil
local targetCFrame = CFrame.new(1771.68, 10.81, 849.23)

