                                            end
                                        end
                                    end
                                end
                            end
                            
                            if processedTarget then return end
                            
                            local scanList = {}
                            for _, npc in pairs(npcsFolder:GetChildren()) do
                                table.insert(scanList, npc)
                            end
                            
                            local rooms = Workspace:FindFirstChild("Rooms")
