                            for _, npc in pairs(scanList) do
                                if not _G.APW_AutoProcess then break end
                                if (npc:IsA("Model") or npc:IsA("Part") or npc:IsA("MeshPart")) and not isSkinwalker(npc) and hasEnabledPrompt(npc) then
