                                    if pos then
                                        safeTeleport(pos)
                                        local interacted = false
                                        for _, desc in pairs(npc:GetDescendants()) do
                                            if desc:IsA("ProximityPrompt") and desc.Enabled then
                                                if firePrompt(desc) then interacted = true; break end
