        local pAction = prompt.ActionText and string.lower(prompt.ActionText) or ""
        
        if string.find(pName, "report") or string.find(pAction, "report") or string.find(pAction, "报告") then
            return
        end

        debounce = true
        task.spawn(function()
            pcall(function()
                fireproximityprompt(prompt)
            end)
        end)
        task.wait(0.1)
        debounce = false
    end
end)

