                    if npc:IsA("Model") and npc.Name == "PhotoVisitor" then
                        npc:SetAttribute("Cursed", false)
                        npc:SetAttribute("Skinwalker", false)
                    end
                end
            end
            WindUI:Notify({Title = "防诅咒", Content = state and "已开启" or "已关闭", Duration = 3})
        end
    })

