local collectEnabled = false
local collectThread = nil

local function collectNearestOre()
    local player = game.Players.LocalPlayer
    local char = player.Character
    if not char then return end
    local root = char:FindFirstChild("HumanoidRootPart")
    if not root then return end

    local nearestOre = nil
    local nearestDist = math.huge

    for _, v in ipairs(workspace:GetDescendants()) do
        if v:IsA("BasePart") and v.Name:find("Ore") then
            local dist = (root.Position - v.Position).Magnitude
            if dist < nearestDist then
                nearestDist = dist
                nearestOre = v
            end
        end
    end

    if nearestOre then
        local args = { nearestOre.Name }
        game:GetService("ReplicatedStorage")
            :WaitForChild("shared/network/MiningNetwork@GlobalMiningEvents")
            :WaitForChild("CollectItem")
            :FireServer(unpack(args))
    end
end

local function startCollect()
    if collectThread then return end
    collectEnabled = true
    collectThread = task.spawn(function()
        while collectEnabled do
            pcall(collectNearestOre)
            task.wait(0.1)
        end
        collectThread = nil
    end)
end

local function stopCollect()
    collectEnabled = false
    if collectThread then
        collectThread = nil
    end
end

local sellPosition = Vector3.new(1021.2, 245.0, -65.6)

local function teleportAndSell()
    local player = game.Players.LocalPlayer
    local char = player.Character
    if not char then return end
    local root = char:FindFirstChild("HumanoidRootPart")
    if not root then return end

    local originalPos = root.Position

    root.CFrame = CFrame.new(sellPosition)
    task.wait(0.5)

    pcall(function()
        game:GetService("ReplicatedStorage"):WaitForChild("Ml"):WaitForChild("SellInventory"):FireServer()
    end)
    task.wait(0.3)

    root.CFrame = CFrame.new(originalPos)
    
    WindUI:Notify({Title = "出售完成", Duration = 2})
end

