if num and num > 0 then
gingerbreadAmount = num
end
end
})
Main:Button({
Title = "获得姜饼人",
Icon = "cookie",
Callback = function()
pcall(function()
LocalPlayer:SetAttribute("gingerbread", gingerbreadAmount)
end)
