if num and num > 0 then
moneyAmount = num
end
end
})
Main:Button({
Title = "获得金钱",
Icon = "dollar-sign",
Callback = function()
pcall(function()
local moneydata = tostring(moneyAmount)
moneyDisplay.current = moneydata
moneyDisplay.tweenTo = moneydata
moneyDisplay.caChing()
end)
